# ---------- LLM ----------

class BaseLLM:
    """Common interface: .generate(prompt, system) -> str, with SHA1 cache."""
    def __init__(self, cache_enabled=True, namespace: str = "base"):
        self._cache: Dict[str, str] = {}
        self._cache_signature: Dict[str, str] = {}
        self.namespace = namespace
        self.cache_enabled = cache_enabled
        self.call_count = 0
        self.cache_hits = 0
        self.latency_s = 0.0

    def _raw(self, prompt: str, system: Optional[str]) -> str:
        raise NotImplementedError

    def generate(self, prompt: str, system: Optional[str] = None,
                 cache_key: Optional[str] = None) -> str:
        signature = _sha1(self.namespace + "\n" + (system or "") + "\n" + prompt)
        k = cache_key or signature
        if k in self._cache_signature and self._cache_signature[k] != signature:
            raise RuntimeError("cache key reused for a different LLM prompt")
        self._cache_signature.setdefault(k, signature)
        if self.cache_enabled and k in self._cache:
            self.cache_hits += 1
            return self._cache[k]
        t0 = time.time()
        out = self._raw(prompt, system)
        self.latency_s += time.time() - t0
        if self.cache_enabled:
            self._cache[k] = out
        return out

    @property
    def stats(self):
        return {"namespace": self.namespace, "api_calls": self.call_count,
                "cache_hits": self.cache_hits, "cache_size": len(self._cache),
                "latency_s": round(self.latency_s, 2)}

    def reset_stats(self):
        self.call_count = 0; self.cache_hits = 0; self.latency_s = 0.0


class NebiusLLM(BaseLLM):
    """OpenAI-compatible backend with retry, caching, and accounting."""
    def __init__(self, client, model, temperature=0.2, max_tokens=400, cache_enabled=True):
        super().__init__(cache_enabled, namespace=f"{getattr(client, 'base_url', 'endpoint')}::{model}")
        self.client, self.model = client, model
        self.temperature, self.max_tokens = temperature, max_tokens

    def _raw(self, prompt, system):
        from tenacity import retry, wait_exponential, stop_after_attempt

        @retry(wait=wait_exponential(min=1, max=30), stop=stop_after_attempt(5))
        def _call(msgs):
            self.call_count += 1
            r = self.client.chat.completions.create(
                model=self.model, messages=msgs,
                temperature=self.temperature, max_tokens=self.max_tokens)
            return (r.choices[0].message.content or "").strip()

        msgs = ([{"role": "system", "content": system}] if system else []) + \
               [{"role": "user", "content": prompt}]
        return _call(msgs)


class MockLLM(BaseLLM):
    """
    Offline stand-in for dry runs and CI. Deliberately reproduces the two
    pathologies we study, so the pipeline can be validated end to end:
      * declaration collapse  -> returns SEQUENTIAL with high probability
      * narrative-evaluation  -> returns a small positive shift
    `collapse_p` controls how degenerate the declaration prior is.
    """
    def __init__(self, collapse_p: float = 0.93, seed: int = 0, cache_enabled=True):
        super().__init__(cache_enabled, namespace=f"mock::{collapse_p}::{seed}")
        self.collapse_p = collapse_p
        self._rng = np.random.default_rng(seed)

    def _raw(self, prompt, system):
        self.call_count += 1
        s = (system or "")
        if "PLAN MODE" in s:
            m = "SEQUENTIAL" if self._rng.random() < self.collapse_p else \
                str(self._rng.choice(["PREDEFINED", "HIERARCHICAL", "SEARCH"]))
            return json.dumps({"mode": m, "target_mode": "HIGH_LOAD", "theme": "ECONOMIC",
                               "depth": 2, "branching": 4, "replan_trigger": "ON_VIOLATION",
                               "intensity": 0.55, "confidence": 0.7,
                               "reasoning": "mock declaration"})
        if "CRITIC" in s:
            return json.dumps({"approve": True, "risk_level": "LOW",
                               "adjusted_intensity": 0.55, "note": "mock critic"})
        if "evaluate how persuasive" in s.lower():
            return json.dumps({"shift": float(np.round(self._rng.normal(0.08, 0.07), 3)),
                               "persuaded": True, "reason": "mock"})
        if "narrative" in s.lower() or "persuasive message" in s.lower():
            return "Curtailing for the next hour keeps the feeder within limits and avoids a rolling outage for everyone on your lateral."
        return "OK"

