# ---------- feeder physics ----------

@dataclass
class FeederSpec:
    n_laterals: int = 4
    nodes_per_lateral: int = 10
    s_base_kva: float = 1000.0
    line_r_pu: float = 0.022          # per segment, on S_base
    line_x_pu: float = 0.014
    v_root_pu: float = 1.0
    v_min_pu: float = 0.95
    v_max_pu: float = 1.05
    head_cap_kw: float = 1100.0       # feeder-head import limit
    pf: float = 0.95                  # load power factor


def build_feeder(spec: FeederSpec, seed: int = 0) -> nx.DiGraph:
    """Radial distribution feeder: root (substation) -> laterals -> nodes."""
    rng = np.random.default_rng(seed)
    T = nx.DiGraph()
    T.add_node(0, kind="substation", lateral=-1, depth=0)
    nid = 1
    for L in range(spec.n_laterals):
        parent = 0
        for d in range(spec.nodes_per_lateral):
            T.add_node(nid, kind="prosumer", lateral=L, depth=d + 1)
            T.add_edge(parent, nid, r=spec.line_r_pu, x=spec.line_x_pu)
            parent = nid
            nid += 1
    # heterogeneous ratings
    for n in T.nodes:
        if n == 0:
            continue
        T.nodes[n]["peak_kw"] = float(rng.uniform(28, 62))
        T.nodes[n]["pv_kw"] = float(rng.uniform(0, 26))
        T.nodes[n]["flex_frac"] = float(rng.uniform(0.25, 0.65))   # curtailable share
    return T


def load_profile(T: nx.DiGraph, horizon: int = 24, seed: int = 0) -> Tuple[np.ndarray, np.ndarray]:
    """
    Cooling-dominated demand with a late-afternoon peak, plus a PV bell.
    Returns (load_kw[n_nodes, horizon], pv_kw[n_nodes, horizon]); index 0 unused.
    """
    rng = np.random.default_rng(seed)
    h = np.arange(horizon)
    # cooling load: broad afternoon peak around 17h
    shape = 0.42 + 0.58 * np.exp(-0.5 * ((h - 17.0) / 3.6) ** 2) + \
            0.16 * np.exp(-0.5 * ((h - 8.0) / 2.2) ** 2)
    # PV bell centred at 12.5h
    pv_shape = np.clip(np.exp(-0.5 * ((h - 12.5) / 3.0) ** 2) - 0.06, 0, None)
    pv_shape = pv_shape / pv_shape.max()

    N = max(T.nodes) + 1
    load = np.zeros((N, horizon)); pv = np.zeros((N, horizon))
    for n in T.nodes:
        if n == 0:
            continue
        jitter = rng.normal(1.0, 0.07, horizon).clip(0.75, 1.25)
        load[n] = T.nodes[n]["peak_kw"] * shape * jitter
        pv[n] = T.nodes[n]["pv_kw"] * pv_shape * rng.normal(1.0, 0.05, horizon).clip(0.8, 1.2)
    return load, pv


def lindistflow(T: nx.DiGraph, spec: FeederSpec, net_kw: np.ndarray) -> Tuple[np.ndarray, float]:
    """
    Linearised DistFlow on a radial tree.
      v_j = v_i - 2 (r_ij P_ij + x_ij Q_ij),  v = |V|^2 in pu
    net_kw[n] > 0 is net *consumption* at node n. Returns (|V| pu per node, head kW).
    """
    N = max(T.nodes) + 1
    p_pu = net_kw / spec.s_base_kva
    q_pu = p_pu * math.tan(math.acos(spec.pf))

    order = list(nx.dfs_postorder_nodes(T, 0))
    P = np.zeros(N); Q = np.zeros(N)        # flow from parent into node (incl. downstream)
    for n in order:
        if n == 0:
            continue
        P[n] = p_pu[n] + sum(P[c] for c in T.successors(n))
        Q[n] = q_pu[n] + sum(Q[c] for c in T.successors(n))

    v2 = np.full(N, spec.v_root_pu ** 2)
    for n in nx.bfs_tree(T, 0).nodes:
        if n == 0:
            continue
        par = next(T.predecessors(n))
        e = T.edges[par, n]
        v2[n] = v2[par] - 2.0 * (e["r"] * P[n] + e["x"] * Q[n])
    v = np.sqrt(np.clip(v2, 1e-6, None))
    head_kw = float(sum(P[c] for c in T.successors(0)) * spec.s_base_kva)
    return v, head_kw


def voltage_sensitivity(T: nx.DiGraph, spec: FeederSpec) -> np.ndarray:
    """
    dv_min/dp at each node: how much curtailing 1 kW at node n lifts the worst
    voltage on the feeder. Used for the oracle allocator and for the adversarial
    targeting mode (which maximises the *opposite*).
    """
    N = max(T.nodes) + 1
    sens = np.zeros(N)
    base = np.zeros(N)
    for n in T.nodes:
        if n != 0:
            base[n] = T.nodes[n]["peak_kw"]
    v0, _ = lindistflow(T, spec, base)
    for n in T.nodes:
        if n == 0:
            continue
        pert = base.copy(); pert[n] -= 1.0
        v1, _ = lindistflow(T, spec, pert)
        sens[n] = float(v1.min() - v0.min())
    return sens


def grid_metrics(T: nx.DiGraph, spec: FeederSpec, v: np.ndarray, head_kw: float) -> Dict[str, float]:
    nodes = [n for n in T.nodes if n != 0]
    vv = v[nodes]
    return {
        "v_min": float(vv.min()),
        "v_max": float(vv.max()),
        "v_violation": float(np.sum(np.clip(spec.v_min_pu - vv, 0, None))),
        "n_v_violations": int(np.sum(vv < spec.v_min_pu)),
        "head_kw": float(head_kw),
        "head_over_kw": float(max(0.0, head_kw - spec.head_cap_kw)),
        "cap_violated": bool(head_kw > spec.head_cap_kw),
    }

