PLAN_MODES   = ["PREDEFINED", "SEQUENTIAL", "HIERARCHICAL", "SEARCH"]
TARGET_MODES = ["HEAD", "LATERAL_ENDS", "HIGH_LOAD", "RANDOM"]   # feeder targeting rules
THEMES       = ["MORAL", "ECONOMIC", "IDENTITY", "HYBRID"]       # operator message framing
REPLAN_TRIG  = ["NONE", "EVERY_STEP", "ON_VIOLATION"]

THEME_EFFECTS = {"MORAL": 1.15, "ECONOMIC": 1.05, "IDENTITY": 1.10, "HYBRID": 1.20}


@dataclass
class DispatchPolicy:
    """
    A typed planning policy. Modes become points in a structured space
    (depth, branching, replanning trigger, targeting, intensity), enabling
    static validation and component-level attribution.
    """
    mode: str = "SEQUENTIAL"
    target_mode: str = "HIGH_LOAD"
    theme: str = "ECONOMIC"
    depth: int = 2                 # decomposition depth (HIERARCHICAL)
    branching: int = 4             # N candidates (SEARCH)
    replan_trigger: str = "ON_VIOLATION"
    intensity: float = 0.5         # requested curtailment as a share of flexible load
    budget_s: float = 30.0         # latency budget for this dispatch decision
    confidence: float = 0.7
    reasoning: str = ""
    # provenance
    declared_by: str = "natural"   # natural | hybrid | forced
    true_target_mode: Optional[str] = None   # adversarial split (declared vs executed)

    def to_dict(self):
        return asdict(self)


def normalize_policy(j: Dict[str, Any]) -> DispatchPolicy:
    def pick(x, allowed, default):
        s = str(x).upper().strip()
        return s if s in allowed else default

    def num(x, lo, hi, default):
        try:
            return float(np.clip(float(x), lo, hi))
        except Exception:
            return default

    return DispatchPolicy(
        mode=pick(j.get("mode"), PLAN_MODES, "SEQUENTIAL"),
        target_mode=pick(j.get("target_mode"), TARGET_MODES, "HIGH_LOAD"),
        theme=pick(j.get("theme"), THEMES, "ECONOMIC"),
        depth=int(num(j.get("depth", 2), 1, 3, 2)),
        branching=int(num(j.get("branching", 4), 1, 8, 4)),
        replan_trigger=pick(j.get("replan_trigger"), REPLAN_TRIG, "ON_VIOLATION"),
        intensity=num(j.get("intensity", 0.5), 0.0, 1.0, 0.5),
        budget_s=num(j.get("budget_s", 30.0), 1.0, 600.0, 30.0),
        confidence=num(j.get("confidence", 0.7), 0.0, 1.0, 0.7),
        reasoning=str(j.get("reasoning", ""))[:400],
    )


def type_check(pol: DispatchPolicy) -> List[str]:
    """The verifier's static half: PPL well-formedness. Returns list of type errors."""
    errs = []
    if pol.mode == "HIERARCHICAL" and pol.depth < 2:
        errs.append("HIERARCHICAL_DEPTH_LT_2")
    if pol.mode == "SEARCH" and pol.branching < 2:
        errs.append("SEARCH_BRANCHING_LT_2")
    if pol.mode == "PREDEFINED" and pol.replan_trigger != "NONE":
        errs.append("PREDEFINED_WITH_REPLAN_TRIGGER")
    if pol.mode == "SEQUENTIAL" and pol.replan_trigger == "NONE":
        errs.append("SEQUENTIAL_WITHOUT_REPLAN_TRIGGER")
    if not (0.0 <= pol.intensity <= 1.0):
        errs.append("INTENSITY_OUT_OF_RANGE")
    return errs

# ===== upstream cell 11 =====
# ---------- task features + hybrid declaration base ----------

def task_features(T, spec, net_kw_forecast: np.ndarray, t: int, horizon: int,
                  noise: float = 0.0, rng=None) -> Dict[str, float]:
    """
    Cheap, LLM-free features of the *situation*, computed from the (possibly
    noisy) forecast. These form the base distribution over plan modes in the
    hybrid declaration used for bounded, feature-conditioned mode selection.
    """
    rng = rng or np.random.default_rng(0)
    fut = net_kw_forecast[1:, t:]
    if fut.size == 0:
        fut = net_kw_forecast[1:, -1:]
    tot = fut.sum(axis=0)
    obs = tot * (1.0 + rng.normal(0, noise, tot.shape)) if noise > 0 else tot

    over = np.clip(obs - spec.head_cap_kw, 0, None)
    stress = float(over.max() / max(spec.head_cap_kw, 1e-6))
    burden = float(over.sum() / max(spec.head_cap_kw, 1e-6))     # how many cap-hours of work
    steps_left = float(horizon - t)
    volatility = float(np.std(np.diff(obs)) / (np.mean(np.abs(obs)) + 1e-6)) if obs.size > 2 else 0.0
    spatial = float(np.std(fut[:, 0]) / (np.mean(fut[:, 0]) + 1e-6))
    return {"stress": stress, "burden": burden, "steps_left": steps_left,
            "volatility": volatility, "spatial_spread": spatial,
            "horizon_frac": steps_left / max(horizon, 1)}


def base_mode_logits(f: Dict[str, float]) -> np.ndarray:
    """
    Hand-specified, monotone, LLM-free prior over the four modes.
    Rationale (all falsifiable, and E2 measures whether they hold):
      PREDEFINED   -- short horizon, low volatility, mild stress
      SEQUENTIAL   -- default; favoured by volatility
      HIERARCHICAL -- large spatial spread and long horizon (decomposable)
      SEARCH       -- high stress with slack time to afford rollouts
    """
    z = np.array([
        0.9 - 2.2 * f["stress"] - 3.0 * f["volatility"] - 1.0 * f["horizon_frac"],   # PREDEFINED
        0.6 + 2.0 * f["volatility"] + 0.4 * f["stress"],                              # SEQUENTIAL
        -0.2 + 2.6 * f["spatial_spread"] + 1.4 * f["horizon_frac"] + 0.8 * f["burden"],  # HIERARCHICAL
        -0.6 + 3.0 * f["stress"] + 1.2 * f["horizon_frac"],                           # SEARCH
    ], dtype=float)
    return z


def softmax(z, temp=1.0):
    z = np.asarray(z, float) / max(temp, 1e-6)
    e = np.exp(z - z.max())
    return e / e.sum()

