def canonical_policy_for_mode(pol: DispatchPolicy, mode: str) -> DispatchPolicy:
    """Return a type-valid variant of ``pol`` for the requested execution mode."""
    out = replace(pol)
    out.mode = mode
    if mode == "PREDEFINED":
        out.depth, out.branching, out.replan_trigger = 1, 1, "NONE"
    elif mode == "SEQUENTIAL":
        out.depth, out.branching, out.replan_trigger = 1, 1, "ON_VIOLATION"
    elif mode == "HIERARCHICAL":
        out.depth, out.branching, out.replan_trigger = max(2, out.depth), 1, "ON_VIOLATION"
    elif mode == "SEARCH":
        out.depth, out.branching, out.replan_trigger = 1, max(2, out.branching), "NONE"
    return out


def estimated_latency(pol: DispatchPolicy, n_laterals: int) -> float:
    """Latency surrogate for the executor that will actually run."""
    base = MODE_COST_S[pol.mode]
    if pol.mode == "HIERARCHICAL":
        depth = max(2, pol.depth)
        base *= (1 + 0.35 * (depth - 1)) * (n_laterals / 4.0)
    if pol.mode == "SEARCH":
        # The search executor always evaluates at least two candidates.
        base *= max(2, pol.branching) / 4.0
    return float(base)


class DispatchCritic:
    """Deadline-aware policy gate with type-valid fallback policies."""
    def __init__(self, llm=None, use_llm: bool = True, enforce_deadline: bool = True):
        self.llm, self.use_llm, self.enforce_deadline = llm, use_llm, enforce_deadline

    def review(self, pol: DispatchPolicy, state: Dict[str, Any],
               deadline_s: float, n_laterals: int) -> Tuple[DispatchPolicy, Dict]:
        meta = {}
        est_before = estimated_latency(pol, n_laterals)
        meta["est_latency_before_gate_s"] = est_before
        meta["deadline_s"] = deadline_s

        if self.enforce_deadline and est_before > deadline_s:
            variants = [canonical_policy_for_mode(pol, mode) for mode in PLAN_MODES]
            fits = [candidate for candidate in variants
                    if estimated_latency(candidate, n_laterals) <= deadline_s
                    and not type_check(candidate)]
            fallback = fits[-1] if fits else variants[0]
            meta["deadline_downgrade"] = {"from": pol.mode, "to": fallback.mode}
            pol = fallback
            pol.confidence *= 0.8

        est_after = estimated_latency(pol, n_laterals)
        meta["est_latency_s"] = est_after

        if self.use_llm and self.llm is not None:
            raw = self.llm.generate(
                "Proposed plan:\n" + json.dumps(pol.to_dict(), indent=2) +
                "\n\nGrid state:\n" + json.dumps(state, indent=2) +
                f"\n\nControl deadline: {deadline_s:.1f} s. Estimated decision latency: {est_after:.1f} s.",
                system=CRITIC_SYSTEM)
            meta["critic_raw"] = raw
            try:
                cj = extract_json(raw)
                approved = bool(cj.get("approve", True))
                risk = str(cj.get("risk_level", "LOW")).upper()
                adj = float(np.clip(float(cj.get("adjusted_intensity", pol.intensity)), 0, 1))
                meta.update({"critic_approved": approved, "critic_risk": risk})
                if not approved:
                    pol.intensity = float(np.clip(adj * 0.6, 0.05, 0.9)); pol.confidence *= 0.7
                elif risk == "HIGH":
                    pol.intensity = float(np.clip(adj * 0.8, 0.05, 0.95))
                elif risk == "MEDIUM":
                    pol.intensity = adj
            except Exception as e:
                meta["critic_error"] = str(e)

        errs = type_check(pol)
        meta["type_errors"] = errs
        return pol, meta

