@dataclass
class Prosumer:
    idx: int
    archetype: str
    archetype_desc: str
    base_bias: float
    resistance: float
    lateral: int
    depth: int
    memory: List[Dict[str, Any]] = field(default_factory=list)
    times_targeted: int = 0
    times_complied: int = 0
    times_exploited: int = 0
    cum_comfort_loss: float = 0.0
    cum_curtailed_kwh: float = 0.0

    def remember(self, e):
        self.memory.append(e)
        if len(self.memory) > 24:
            self.memory = self.memory[-24:]

    def compliance_base(self, neighbour_compliance: float) -> float:
        """
        Game-theoretic base: a repeated public-goods / PD structure on the feeder.
        Complying costs comfort; the stability benefit is shared, so free-riding
        dominates unless enough neighbours comply and exploitation is low.
        """
        recent = self.memory[-6:]
        my_rate = np.mean([m["complied"] for m in recent]) if recent else 0.5
        exploit = self.times_exploited / max(self.times_targeted, 1)
        z = (0.15
             + 1.5 * self.base_bias
             + 1.1 * (neighbour_compliance - 0.5)      # conformity / reciprocity
             - 1.6 * exploit                            # punish being the sucker
             + 0.5 * (my_rate - 0.5)                    # habit
             - 0.35 * min(self.cum_comfort_loss / 6.0, 1.0))   # fatigue
        return float(np.clip(1.0 / (1.0 + np.exp(-z)), 0.02, 0.98))

    def eval_prompt(self, narrative: str, ask_kw: float, neighbour_compliance: float,
                    hour: int) -> str:
        recent = self.memory[-4:]
        hist = "; ".join(f"h{m['t']}:{'curtailed' if m['complied'] else 'declined'}"
                         for m in recent) or "no prior events"
        return (f"Your personality: {self.archetype_desc}\n"
                f"Hour {hour}. You are asked to shed {ask_kw:.1f} kW of flexible load.\n"
                f"Neighbours on your lateral currently complying: {neighbour_compliance:.0%}\n"
                f"Times you curtailed while neighbours did not: {self.times_exploited}\n"
                f"Your recent events: {hist}\n\n"
                f"Message from the operator:\n\"{narrative}\"\n\n"
                f"How much does this message shift your willingness to curtail?")


def create_population(T, seed: int = 0, resistance_mean=0.30, resistance_std=0.15) -> Dict[int, Prosumer]:
    rng = np.random.default_rng(seed)
    pop = {}
    for n in T.nodes:
        if n == 0:
            continue
        a = PERSONALITY_ARCHETYPES[int(rng.integers(0, len(PERSONALITY_ARCHETYPES)))]
        pop[n] = Prosumer(
            idx=n, archetype=a["name"], archetype_desc=a["desc"], base_bias=a["base_bias"],
            resistance=float(np.clip(rng.normal(resistance_mean, resistance_std), 0.0, 0.95)),
            lateral=T.nodes[n]["lateral"], depth=T.nodes[n]["depth"])
    return pop

