# ---------- plan representation ----------

@dataclass
class PlanStep:
    t: int
    allocation: Dict[int, float]      # node -> requested curtailment (kW)
    level: str = "root"               # root | lateral | segment (HIERARCHICAL provenance)
    revision: int = 0
    rationale: str = ""

# ===== upstream cell 16 =====
# ---------- allocation primitives ----------

def flexible_kw(T, net_kw_t: np.ndarray, node: int) -> float:
    return float(max(0.0, net_kw_t[node]) * T.nodes[node]["flex_frac"])


def select_targets(T, target_mode: str, net_kw_t: np.ndarray, sens: np.ndarray,
                   frac: float, rng) -> List[int]:
    nodes = [n for n in T.nodes if n != 0]
    k = max(1, int(round(frac * len(nodes))))
    if target_mode == "HEAD":                 # nodes electrically closest to the substation
        order = sorted(nodes, key=lambda n: T.nodes[n]["depth"])
    elif target_mode == "LATERAL_ENDS":       # deepest nodes: highest voltage leverage
        order = sorted(nodes, key=lambda n: -T.nodes[n]["depth"])
    elif target_mode == "HIGH_LOAD":
        order = sorted(nodes, key=lambda n: -net_kw_t[n])
    elif target_mode == "ADVERSARIAL":        # lowest leverage per kW asked (see E5)
        order = sorted(nodes, key=lambda n: sens[n])
    else:                                     # RANDOM
        order = list(rng.permutation(nodes))
    return order[:k]


def allocate(T, targets: List[int], R_kw: float, net_kw_t: np.ndarray,
             intensity: float) -> Dict[int, float]:
    """Allocate a curtailment target across selected nodes, capped by flexible load."""
    caps = {n: flexible_kw(T, net_kw_t, n) for n in targets}
    total_cap = sum(caps.values())
    if total_cap <= 1e-6:
        return {n: 0.0 for n in targets}
    ask = min(R_kw, total_cap * intensity) if R_kw > 0 else 0.0
    return {n: float(ask * caps[n] / total_cap) for n in targets}


def required_reduction(spec, net_kw_t: np.ndarray) -> float:
    return float(max(0.0, net_kw_t[1:].sum() - spec.head_cap_kw))


def oracle_allocation(T, spec, net_kw_t: np.ndarray, sens: np.ndarray) -> Dict[int, float]:
    """
    Perfect-information, perfect-compliance reference: shed from the highest
    voltage-leverage nodes first until the cap and the voltage floor are met.
    Used for Plan Minimality and for per-scenario oracle regret.
    """
    nodes = sorted([n for n in T.nodes if n != 0], key=lambda n: -sens[n])
    alloc = {}
    cur = net_kw_t.copy()
    for n in nodes:
        v, head = lindistflow(T, spec, cur)
        if head <= spec.head_cap_kw and v[1:].min() >= spec.v_min_pu:
            break
        take = flexible_kw(T, cur, n)
        if take <= 0:
            continue
        alloc[n] = take
        cur[n] -= take
    return alloc

# ===== upstream cell 17 =====
# ---------- executors ----------

class ExecLog:
    def __init__(self):
        self.revisions = 0
        self.levels_used = set(["root"])
        self.candidates = 0
        self.llm_calls_planning = 0
        self.latency_s = 0.0
        self.tool_failures = 0
        self.notes: List[str] = []


def needed_frac(T, spec, net_kw_t: np.ndarray, R_kw: float, compliance_prior: float) -> float:
    """How wide must the call go, given expected compliance? Adaptive, not fixed."""
    tot_flex = sum(flexible_kw(T, net_kw_t, n) for n in T.nodes if n != 0)
    if tot_flex <= 1e-6 or R_kw <= 0:
        return 0.0
    return float(np.clip(1.25 * (R_kw / max(compliance_prior, 0.15)) / tot_flex, 0.05, 1.0))


def _plan_window(T, spec, pol, net_fc, t, window, sens, rng,
                 compliance_prior: float = 0.6, level="root") -> List[PlanStep]:
    steps = []
    for h in range(t, min(t + window, net_fc.shape[1])):
        R = required_reduction(spec, net_fc[:, h])
        tm = pol.true_target_mode or pol.target_mode
        frac = needed_frac(T, spec, net_fc[:, h], R, compliance_prior)
        tg = select_targets(T, tm, net_fc[:, h], sens, frac=frac, rng=rng)
        # ask enough to survive expected non-compliance, never above observed flexibility
        R_ask = R / max(compliance_prior, 0.15)
        al = allocate(T, tg, R_ask, net_fc[:, h], pol.intensity)
        if pol.true_target_mode == "ADVERSARIAL":
            al = {n: 0.6 * kw for n, kw in al.items()}   # covert under-delivery
        steps.append(PlanStep(t=h, allocation=al, level=level,
                              rationale=f"{pol.mode}/{tm}/cp={compliance_prior:.2f}"))
    return steps


def plan_predefined(T, spec, pol, net_fc, t, horizon, sens, rng, log: ExecLog, cp: float = 0.6):
    log.notes.append("plan-once, no revision")
    return _plan_window(T, spec, pol, net_fc, t, horizon - t, sens, rng, cp)


def plan_sequential(T, spec, pol, net_fc, t, horizon, sens, rng, log: ExecLog, cp: float = 0.6):
    log.notes.append("plan-execute-revise")
    return _plan_window(T, spec, pol, net_fc, t, horizon - t, sens, rng, cp)


def plan_hierarchical(T, spec, pol, net_fc, t, horizon, sens, rng, log: ExecLog, cp: float = 0.6):
    """
    Orchestrator -> lateral workers -> (depth 3) segment workers -> leaves.
    Unlike ALFWorld, the decomposition tree is not invented: it is the feeder.
    """
    log.levels_used.update(["lateral"])
    if pol.depth >= 3:
        log.levels_used.add("segment")
    steps: List[PlanStep] = []
    laterals = sorted({T.nodes[n]["lateral"] for n in T.nodes if n != 0})
    for h in range(t, min(t + (horizon - t), net_fc.shape[1])):
        R = required_reduction(spec, net_fc[:, h]) / max(cp, 0.15)
        lat_load = {L: sum(max(0.0, net_fc[n, h]) for n in T.nodes
                           if n != 0 and T.nodes[n]["lateral"] == L) for L in laterals}
        tot = sum(lat_load.values()) or 1.0
        alloc: Dict[int, float] = {}
        for L in laterals:
            R_L = R * lat_load[L] / tot                      # orchestrator split
            members = [n for n in T.nodes if n != 0 and T.nodes[n]["lateral"] == L]
            if pol.depth >= 3:                                # nested: head vs tail segment
                mid = len(members) // 2
                for seg in (members[:mid], members[mid:]):
                    seg_load = sum(max(0.0, net_fc[n, h]) for n in seg) or 1.0
                    R_seg = R_L * seg_load / (sum(max(0.0, net_fc[n, h]) for n in members) or 1.0)
                    tg = select_targets(T.subgraph(seg + [0]) if 0 in T else T,
                                        pol.true_target_mode or pol.target_mode,
                                        net_fc[:, h], sens, 1.0, rng)
                    tg = [n for n in tg if n in seg]
                    alloc.update(allocate(T, tg, R_seg, net_fc[:, h], pol.intensity))
            else:
                tm = pol.true_target_mode or pol.target_mode
                order = select_targets(T, tm, net_fc[:, h], sens, 1.0, rng)
                tg = [n for n in order if n in members][:max(1, int(0.5 * len(members)))]
                alloc.update(allocate(T, tg, R_L, net_fc[:, h], pol.intensity))
        steps.append(PlanStep(t=h, allocation=alloc, level="lateral",
                              rationale=f"HIER d={pol.depth}"))
    log.llm_calls_planning += len(laterals)                   # one worker call per lateral
    return steps


def _rollout_score(T, spec, steps: List[PlanStep], net_fc, expected_compliance: float) -> float:
    """Simulate a candidate plan on the forecast. Lower is better."""
    viol, curt = 0.0, 0.0
    for st in steps:
        cur = net_fc[:, st.t].copy()
        for n, kw in st.allocation.items():
            take = kw * expected_compliance
            cur[n] -= take; curt += take
        v, head = lindistflow(T, spec, cur)
        m = grid_metrics(T, spec, v, head)
        viol += m["head_over_kw"] + 4000.0 * m["v_violation"]
    return viol + 0.25 * curt


def plan_search(T, spec, pol, net_fc, t, horizon, sens, rng, log: ExecLog, cp: float = 0.6):
    expected_compliance = cp
    """N candidate plans, each rolled out against the physics, best-of-N kept."""
    cands = []
    grid = [(tm, inten) for tm in ["HIGH_LOAD", "LATERAL_ENDS", "HEAD", "RANDOM"]
            for inten in (pol.intensity, min(1.0, pol.intensity * 1.35))]
    rng.shuffle(grid)
    for (tm, inten) in grid[:max(2, pol.branching)]:
        p2 = DispatchPolicy(**{**pol.to_dict(), "target_mode": tm, "intensity": inten})
        p2.true_target_mode = pol.true_target_mode
        steps = _plan_window(T, spec, p2, net_fc, t, horizon - t, sens, rng, cp)
        cands.append((_rollout_score(T, spec, steps, net_fc, expected_compliance), tm, inten, steps))
    cands.sort(key=lambda c: c[0])
    log.candidates = len(cands)
    log.llm_calls_planning += len(cands)
    log.notes.append(f"best-of-{len(cands)} -> {cands[0][1]}@{cands[0][2]:.2f}")
    return cands[0][3]


ROUTER = {"PREDEFINED": plan_predefined, "SEQUENTIAL": plan_sequential,
          "HIERARCHICAL": plan_hierarchical, "SEARCH": plan_search}

# ===== upstream cell 18 =====
# ---------- verifier ----------

def classify_executed_mode(log: ExecLog) -> str:
    """Deterministic classifier for the execution pattern that actually ran."""
    if log.candidates > 1:
        return "SEARCH"
    if "lateral" in log.levels_used or "segment" in log.levels_used:
        return "HIERARCHICAL"
    if log.revisions > 0:
        return "SEQUENTIAL"
    return "PREDEFINED"


def plan_metrics(realized: List[Dict], feasible_flags: List[bool], churn: List[float],
                 targeting_fidelity: List[float], hourly: List[Dict]) -> Dict[str, float]:
    """
    Trace-level planning metrics grounded in the physical environment, plus
    directive realisation for strategic multi-agent response.

      Faithfulness  -> targeting fidelity: did the executed targeting match the
                       policy that was declared? (Jaccard, per dispatch.) This is
                       the metric an adversarial aggregator has to defeat.
      Groundedness  -> share of directives feasible against the TRUE flexible
                       load, with a 5% tolerance. Degrades with forecast error,
                       so it is the observability channel (see E3).
      Minimality    -> oracle kWh / actual kWh, evaluated ONLY on hours that
                       ended without a violation. Minimality is meaningless on a
                       failed hour: under-shedding is cheap and useless.
      Coherence     -> 1 - normalised churn between consecutive plan revisions.
      Realization   -> realized / requested kW. NEW: the coordination axis. In a
                       single-agent benchmark this is identically 1.
    """
    req = sum(r["requested_kw"] for r in realized)
    rea = sum(r["realized_kw"] for r in realized)
    realization = float(np.clip(rea / max(req, 1e-6), 0.0, 1.0))

    ok = [h for h in hourly if not h["violated"] and h["actual_kwh"] > 1e-6]
    if ok:
        minim = float(np.mean([min(1.0, h["oracle_kwh"] / h["actual_kwh"]) for h in ok]))
    else:
        minim = float("nan")

    return {
        "plan_faithfulness": float(np.mean(targeting_fidelity)) if targeting_fidelity else 1.0,
        "plan_groundedness": float(np.mean(feasible_flags)) if feasible_flags else 1.0,
        "plan_minimality": minim,
        "plan_coherence": float(np.clip(1.0 - np.mean(churn), 0.0, 1.0)) if churn else 1.0,
        "directive_realization": realization,
    }


FAILURE_CAUSES = ["NONE", "DECOMPOSITION_ERROR", "STATE_INFERENCE", "TOOL_FAIL",
                  "BUDGET_EXHAUSTION", "COORDINATION_FAILURE", "NON_RECOVERY"]


def label_failure(res: Dict[str, Any]) -> str:
    """
    Deterministic, auditable failure labelling. Order matters: the first cause
    that fires is recorded as the primary cause.
    """
    if res["violation_hours"] == 0:
        return "NONE"
    if res["budget_exhausted_steps"] > 0:
        return "BUDGET_EXHAUSTION"
    if res["tool_failures"] > 0 and res["plan_groundedness"] < 0.9:
        return "TOOL_FAIL"
    if res["plan_groundedness"] < 0.75:
        return "DECOMPOSITION_ERROR"
    if res["forecast_mae_frac"] > 0.08 and res["plan_faithfulness"] > 0.6:
        return "STATE_INFERENCE"
    if res["mean_compliance"] < 0.45:
        return "COORDINATION_FAILURE"
    if res["revisions"] > 0:
        return "NON_RECOVERY"
    return "DECOMPOSITION_ERROR"

# ===== upstream cell 19 =====
# ---------- episode ----------

@dataclass
class EpisodeConfig:
    seed: int = 0
    horizon: int = 24
    declaration: str = "natural"        # natural | hybrid | forced | none
    forced_mode: Optional[str] = None
    state_noise: float = 0.10           # observability: forecast error, sigma (fraction)
    deadline_s: float = 30.0            # control interval available for the decision
    use_critic: bool = True
    critic_llm: bool = False
    llm_agents: bool = True             # prosumers evaluate the narrative with an LLM
    llm_agent_frac: float = 0.4         # subsample of targeted nodes that get an LLM call
    tool_fail_p: float = 0.02           # telemetry read failure per dispatch
    adversarial: bool = False           # declared target set may differ from the executed target set
    honesty: float = 1.0                # 1.0 = declared == true; 0.0 = fully covert
    resistance_mean: float = 0.30
    label: str = ""


def run_episode(cfg: EpisodeConfig, spec: FeederSpec, llm, feeder_seed: int = 1) -> Dict[str, Any]:
    set_seed(cfg.seed)
    # Independent random streams prevent planning-internal draws from changing
    # forecast, tool, adversarial, or prosumer-response randomness.
    rng_forecast = np.random.default_rng(np.random.SeedSequence([cfg.seed, 0xF01]))
    rng_planning = np.random.default_rng(np.random.SeedSequence([cfg.seed, 0xA11]))

    T = build_feeder(spec, seed=feeder_seed)
    load, pv = load_profile(T, cfg.horizon, seed=feeder_seed * 100 + cfg.seed)
    net_true = load - pv
    net_fc = net_true * (1.0 + rng_forecast.normal(0, cfg.state_noise, net_true.shape))
    net_fc[0, :] = 0.0
    sens = voltage_sensitivity(T, spec)
    pop = create_population(T, seed=cfg.seed, resistance_mean=cfg.resistance_mean)

    log = ExecLog()
    rows, realized, feasible_flags, churn, plan_log = [], [], [], [], []
    targeting_fid, targeting_lev, hourly = [], [], []
    curtailed_kwh = oracle_kwh = 0.0
    violation_hours = deadline_misses = deadline_downgrades = 0
    compliance_hist: List[float] = []
    prev_plan: Optional[List[PlanStep]] = None
    plan: Optional[List[PlanStep]] = None
    pol: Optional[DispatchPolicy] = None
    declared_modes: List[str] = []
    narrative = ""
    critic = DispatchCritic(llm, use_llm=cfg.critic_llm) if cfg.use_critic else None

    for t in range(cfg.horizon):
        feats = task_features(T, spec, net_fc, t, cfg.horizon, noise=0.0, rng=rng_planning)
        need_plan = (plan is None) or (t > (plan[-1].t if plan else -1))
        replan = False
        if plan is not None and pol is not None and not need_plan:
            if pol.replan_trigger == "EVERY_STEP":
                replan = True
            elif pol.replan_trigger == "ON_VIOLATION" and rows and rows[-1]["cap_violated"]:
                replan = True

        if need_plan or replan:
            state = {"t": t, "hour": t, **{k: round(v, 4) for k, v in feats.items()},
                     "head_cap_kw": spec.head_cap_kw,
                     "forecast_head_kw": round(float(net_fc[1:, t].sum()), 1),
                     "v_min_last": round(rows[-1]["v_min"], 4) if rows else 1.0,
                     "mean_compliance": round(float(np.mean(compliance_hist)), 3) if compliance_hist else 0.5}

            dmeta = {}
            event = "declaration" if need_plan else "revision"
            if need_plan:                     # fresh declaration
                if cfg.declaration == "natural":
                    pol, dmeta = declare_natural(llm, state)
                elif cfg.declaration == "hybrid":
                    pol, dmeta = declare_hybrid(llm, state, feats, rng=rng_planning)
                elif cfg.declaration == "forced":
                    pol, dmeta = declare_forced(cfg.forced_mode, feats)
                else:
                    pol, dmeta = declare_forced("PREDEFINED", feats)
                declared_modes.append(pol.mode)

                if critic is not None:
                    pol, cmeta = critic.review(pol, state, cfg.deadline_s, spec.n_laterals)
                    if cmeta.get("deadline_downgrade"):
                        deadline_downgrades += 1
                    dmeta.update(cmeta)
            else:
                log.revisions += 1

            # Every executor invocation consumes decision time, including revisions.
            est = estimated_latency(pol, spec.n_laterals)
            log.latency_s += est
            if est > cfg.deadline_s:
                deadline_misses += 1
            plan_log.append({"t": t, "event": event, **pol.to_dict(),
                             "est_latency_s": est,
                             "type_errors": ";".join(dmeta.get("type_errors", [])),
                             "base_probs": dmeta.get("base_probs")})

            if cfg.adversarial and pol is not None:     # declared-vs-true split, per decision
                rng_adv = np.random.default_rng(
                    np.random.SeedSequence([cfg.seed, 0xAD0, t]))
                pol.true_target_mode = "ADVERSARIAL" if rng_adv.random() > cfg.honesty else None

            rng_tool = np.random.default_rng(
                np.random.SeedSequence([cfg.seed, 0x7001, t]))
            if rng_tool.random() < cfg.tool_fail_p:      # telemetry read failure
                log.tool_failures += 1
                obs = net_fc[:, t:] * 0.0 + net_fc[:, max(t - 1, 0):max(t - 1, 0) + 1]
                src = np.repeat(net_fc[:, max(t - 1, 0):max(t - 1, 0) + 1], cfg.horizon - t, axis=1)
            else:
                src = net_fc[:, t:]
            fc = np.zeros_like(net_fc); fc[:, t:] = src[:, :cfg.horizon - t]
            fc[:, :t] = net_fc[:, :t]

            # compliance prior: only the replanning modes get to learn it
            if pol.mode in ("SEQUENTIAL", "HIERARCHICAL") and compliance_hist:
                cp = float(np.clip(np.mean(compliance_hist[-4:]), 0.15, 0.98))
            else:
                cp = 0.60
            new_plan = ROUTER[pol.mode](T, spec, pol, fc, t, cfg.horizon, sens, rng_planning, log, cp)
            if prev_plan is not None:
                a = {s.t: sum(s.allocation.values()) for s in prev_plan if s.t >= t}
                b = {s.t: sum(s.allocation.values()) for s in new_plan if s.t >= t}
                keys = set(a) | set(b)
                if keys:
                    churn.append(float(np.mean([abs(a.get(k, 0) - b.get(k, 0)) /
                                                max(a.get(k, 0), b.get(k, 0), 1e-6) for k in keys])))
            prev_plan = plan = new_plan

        step = next((s for s in plan if s.t == t), None)
        alloc = step.allocation if step else {}

        if alloc:   # verifier: does executed targeting match the DECLARED policy?
            issued = {n for n, kw in alloc.items() if kw > 1e-6}
            if issued:   # only hours with an actual dispatch are scored
                honest = set(select_targets(T, pol.target_mode, net_fc[:, t], sens,
                                            frac=len(issued) / max(len(pop), 1),
                                            rng=np.random.default_rng(cfg.seed + t)))
                targeting_fid.append(len(issued & honest) / max(len(issued | honest), 1))
                lev_i = float(np.mean([sens[n] for n in issued]))
                lev_h = float(np.mean([sens[n] for n in honest])) if honest else lev_i
                targeting_lev.append(lev_i / max(lev_h, 1e-12))

        # ----- narrative (one per dispatch, reused across targets) -----
        if alloc and cfg.llm_agents:
            narrative_prompt = (
                f"Framing: {pol.theme}. Hour {t}. Feeder is "
                f"{max(0.0, net_true[1:, t].sum() - spec.head_cap_kw):.0f} kW "
                "over its import limit."
            )
            narrative = llm.generate(narrative_prompt, system=NARRATIVE_GEN_SYSTEM)

        # ----- prosumer compliance (game-theoretic base + bounded LLM shift) -----
        cur = net_true[:, t].copy()
        lat_comp: Dict[int, List[float]] = {}
        complied_nodes = []
        for n, kw in alloc.items():
            if kw <= 1e-6:
                continue
            ag = pop[n]
            ag.times_targeted += 1
            nb = [m for m in pop if pop[m].lateral == ag.lateral and m != n]
            nb_comp = float(np.mean([np.mean([e["complied"] for e in pop[m].memory[-3:]])
                                     for m in nb if pop[m].memory])) if any(pop[m].memory for m in nb) else 0.5
            p = ag.compliance_base(nb_comp)

            # Common random numbers keyed by (seed, hour, node): the same latent
            # willingness and realisation draws are available to every planning mode.
            rng_agent = np.random.default_rng(
                np.random.SeedSequence([cfg.seed, 0xA63, t, int(n)]))
            u_llm, u_comply, u_realise = rng_agent.random(3)

            shift = 0.0
            if cfg.llm_agents and narrative and u_llm < cfg.llm_agent_frac:
                eval_prompt = ag.eval_prompt(narrative, kw, nb_comp, t)
                raw = llm.generate(eval_prompt, system=NARRATIVE_EVAL_SYSTEM)
                try:
                    shift = float(np.clip(float(extract_json(raw).get("shift", 0.0)), -0.30, 0.30))
                except Exception:
                    shift = 0.0
            p_final = float(np.clip(p + shift * (1 - ag.resistance) *
                                    THEME_EFFECTS.get(pol.theme, 1.0), 0.02, 0.98))
            complied = bool(u_comply < p_final)

            cap_kw = flexible_kw(T, net_true[:, t], n)
            feasible_flags.append(kw <= cap_kw * 1.05 + 1e-6)
            real = min(kw, cap_kw) * (1.0 if complied else 0.0) * float(0.88 + 0.12 * u_realise)
            cur[n] -= real
            curtailed_kwh += real
            realized.append({"t": t, "node": n, "requested_kw": kw, "realized_kw": real,
                             "complied": complied, "archetype": ag.archetype,
                             "depth": ag.depth, "lateral": ag.lateral,
                             "p_base": p, "llm_shift": shift})
            ag.remember({"t": t, "complied": complied, "kw": real})
            ag.times_complied += int(complied)
            ag.cum_curtailed_kwh += real
            ag.cum_comfort_loss += real / max(cap_kw, 1e-6)
            lat_comp.setdefault(ag.lateral, []).append(float(complied))
            if complied:
                complied_nodes.append(n)

        for n in complied_nodes:                      # exploitation bookkeeping
            if np.mean(lat_comp.get(pop[n].lateral, [1.0])) < 0.4:
                pop[n].times_exploited += 1

        comp_rate = float(np.mean([r["complied"] for r in realized if r["t"] == t])) \
            if any(r["t"] == t for r in realized) else np.nan
        if not np.isnan(comp_rate):
            compliance_hist.append(comp_rate)

        v, head = lindistflow(T, spec, cur)
        m = grid_metrics(T, spec, v, head)
        orc_h = float(sum(oracle_allocation(T, spec, net_true[:, t], sens).values()))
        oracle_kwh += orc_h
        viol_now = bool(m["cap_violated"] or m["n_v_violations"] > 0)
        violation_hours += int(viol_now)
        hourly.append({"t": t, "violated": viol_now, "oracle_kwh": orc_h,
                       "actual_kwh": float(sum(r["realized_kw"] for r in realized if r["t"] == t))})

        rows.append({"t": t, **m, "requested_kw": float(sum(alloc.values())),
                     "curtailed_kw": float(sum(r["realized_kw"] for r in realized if r["t"] == t)),
                     "compliance": comp_rate, "mode": pol.mode,
                     "declared_by": pol.declared_by, "label": cfg.label})

    df = pd.DataFrame(rows)
    rdf = pd.DataFrame(realized)
    executed_mode = classify_executed_mode(log)
    pm = plan_metrics(realized, feasible_flags, churn, targeting_fid, hourly)
    fc_mae = float(np.mean(np.abs(net_fc[1:] - net_true[1:])) / (np.mean(np.abs(net_true[1:])) + 1e-6))

    res = {
        "label": cfg.label, "seed": cfg.seed, "declaration": cfg.declaration,
        "declared_mode_first": declared_modes[0] if declared_modes else None,
        "declared_modes": declared_modes, "executed_mode": executed_mode,
        "mode_match": bool(declared_modes and executed_mode == declared_modes[-1]),
        "violation_hours": violation_hours,
        "head_over_kwh": float(df["head_over_kw"].sum()),
        "v_violation_total": float(df["v_violation"].sum()),
        "v_min": float(df["v_min"].min()),
        "curtailed_kwh": curtailed_kwh, "oracle_kwh": oracle_kwh,
        "mean_compliance": float(np.nanmean(df["compliance"])) if df["compliance"].notna().any() else np.nan,
        "curtail_gini": gini([p.cum_curtailed_kwh for p in pop.values()]),
        "revisions": log.revisions, "candidates": log.candidates,
        "tool_failures": log.tool_failures,
        "budget_exhausted_steps": deadline_misses,
        "deadline_misses": deadline_misses, "deadline_downgrades": deadline_downgrades,
        "planning_llm_calls": log.llm_calls_planning, "latency_s": log.latency_s,
        "targeting_leverage": float(np.mean(targeting_lev)) if targeting_lev else 1.0,
        "forecast_mae_frac": fc_mae, "state_noise": cfg.state_noise,
        "deadline_s": cfg.deadline_s, "adversarial": cfg.adversarial, "honesty": cfg.honesty,
        **pm,
    }
    res["primary_failure"] = label_failure(res)
    res["objective"] = res["head_over_kwh"] + 4000.0 * res["v_violation_total"] + 0.25 * curtailed_kwh
    return {"summary": res, "timeseries": df, "realized": rdf,
            "plan_log": pd.DataFrame(plan_log), "population": pop}

# ===== upstream cell 21 =====
import itertools


SEEDS = [7, 13, 42, 101, 202]          # committed controlled-evaluation seeds
OUT = "llmstrategicplanning_out_protocol_v3"


def _bar_ci(x):
    x = np.asarray(x, float); x = x[~np.isnan(x)]
    if x.size < 2:
        return (float(x.mean()) if x.size else np.nan), 0.0
    return float(x.mean()), float(1.96 * x.std(ddof=1) / np.sqrt(x.size))


def summarise(rows: List[Dict]) -> pd.DataFrame:
    return pd.DataFrame(rows)

# ===== upstream cell 22 =====
# ---------- E1: declaration collapse ----------

def exp1_declaration(spec, llm, seeds=SEEDS, **kw) -> pd.DataFrame:
    """Does the declaration collapse to one mode, and does the hybrid rule break it?"""
    rows = []
    for decl, seed in itertools.product(["natural", "hybrid"], seeds):
        cfg = EpisodeConfig(seed=seed, declaration=decl, label=f"E1-{decl}", **kw)
        r = run_episode(cfg, spec, llm)["summary"]
        for m in r["declared_modes"]:
            rows.append({"declaration": decl, "seed": seed, "mode": m})
        rows.append({"declaration": decl, "seed": seed, "mode": None,
                     "objective": r["objective"], "violation_hours": r["violation_hours"],
                     "curtailed_kwh": r["curtailed_kwh"]})
    return summarise(rows)


def mode_entropy(df: pd.DataFrame, decl: str) -> float:
    v = df[(df.declaration == decl) & df["mode"].notna()]["mode"].value_counts(normalize=True)
    p = v.values
    return float(-(p * np.log(p + 1e-12)).sum() / np.log(len(PLAN_MODES)))   # normalised

# ===== upstream cell 23 =====
# ---------- E2: forced modes + oracle regret ----------

def exp2_regret(spec, llm, seeds=SEEDS, **kw) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """
    Per-scenario oracle regret. A routed mixture and a fixed pure strategy are
    compared through forced counterfactuals. Regret is computed per seed against
    the best forced mode for that same seed.
    """
    rows = []
    for mode, seed in itertools.product(PLAN_MODES, seeds):
        cfg = EpisodeConfig(seed=seed, declaration="forced", forced_mode=mode,
                            label=f"forced-{mode}", **kw)
        r = run_episode(cfg, spec, llm)["summary"]
        rows.append({"policy": f"forced-{mode}", "mode": mode, "seed": seed, **{
            k: r[k] for k in ["objective", "violation_hours", "curtailed_kwh", "latency_s",
                              "plan_faithfulness", "plan_groundedness", "plan_coherence",
                              "plan_minimality", "directive_realization", "mean_compliance",
                              "curtail_gini", "primary_failure"]}})
    for decl in ["natural", "hybrid"]:
        for seed in seeds:
            cfg = EpisodeConfig(seed=seed, declaration=decl, label=decl, **kw)
            r = run_episode(cfg, spec, llm)["summary"]
            rows.append({"policy": decl, "mode": "ROUTED", "seed": seed, **{
                k: r[k] for k in ["objective", "violation_hours", "curtailed_kwh", "latency_s",
                                  "plan_faithfulness", "plan_groundedness", "plan_coherence",
                                  "plan_minimality", "directive_realization", "mean_compliance",
                                  "curtail_gini", "primary_failure"]}})
    df = summarise(rows)
    best = df[df.policy.str.startswith("forced")].groupby("seed")["objective"].min()
    df["regret"] = df.apply(lambda r: r["objective"] - best[r["seed"]], axis=1)
    reg = df.groupby("policy")["regret"].agg(["mean", "std", "count"]).reset_index()
    return df, reg

# ===== upstream cell 24 =====
# ---------- E3: observability sweep ----------

def exp3_observability(spec, llm, noises=(0.0, 0.05, 0.10, 0.20, 0.30, 0.40),
                       seeds=SEEDS[:3], modes=PLAN_MODES, **kw) -> pd.DataFrame:
    """
    Dose-response for state-inference failure. No text benchmark can do this:
    observability is a knob here, not a property of the environment.
    """
    rows = []
    for nz, mode, seed in itertools.product(noises, modes, seeds):
        cfg = EpisodeConfig(seed=seed, declaration="forced", forced_mode=mode,
                            state_noise=nz, label=f"E3-{mode}-{nz}", **kw)
        r = run_episode(cfg, spec, llm)["summary"]
        rows.append({"state_noise": nz, "mode": mode, "seed": seed,
                     "plan_groundedness": r["plan_groundedness"],
                     "objective": r["objective"], "violation_hours": r["violation_hours"],
                     "forecast_mae_frac": r["forecast_mae_frac"],
                     "primary_failure": r["primary_failure"]})
    return summarise(rows)

# ===== upstream cell 25 =====
# ---------- E4: deadline-aware critic ----------

def exp4_deadline(spec, llm, deadlines=(2.0, 4.0, 8.0, 30.0), seeds=SEEDS[:3], **kw) -> pd.DataFrame:
    """
    The token-cost curve becomes an operational constraint: a plan that cannot be
    decided inside the control interval is infeasible however good it is.
    """
    rows = []
    for dl, use_critic, seed in itertools.product(deadlines, [False, True], seeds):
        cfg = EpisodeConfig(seed=seed, declaration="hybrid", deadline_s=dl,
                            use_critic=use_critic, critic_llm=False,
                            label=f"E4-{dl}-{use_critic}", **kw)
        r = run_episode(cfg, spec, llm)["summary"]
        rows.append({"deadline_s": dl, "critic": use_critic, "seed": seed,
                     "objective": r["objective"], "latency_s": r["latency_s"],
                     "deadline_misses": r["deadline_misses"],
                     "deadline_downgrades": r["deadline_downgrades"],
                     "violation_hours": r["violation_hours"],
                     "executed_mode": r["executed_mode"]})
    return summarise(rows)

# ===== upstream cell 26 =====
# ---------- E5: adversarial aggregator ----------

def exp5_adversarial(spec, llm, honesty=(1.0, 0.75, 0.5, 0.25, 0.0),
                     seeds=SEEDS, **kw) -> pd.DataFrame:
    """
    Objective-substitution stress test. Can executed-mode verification detect an
    operator whose declared and executed modes agree but whose target set changes?
    """
    rows = []
    for h, seed in itertools.product(honesty, seeds):
        cfg = EpisodeConfig(seed=seed, declaration="forced", forced_mode="SEQUENTIAL",
                            adversarial=(h < 1.0), honesty=h, label=f"E5-h{h}", **kw)
        r = run_episode(cfg, spec, llm)["summary"]
        rows.append({"honesty": h, "seed": seed, "mode_match": r["mode_match"],
                     "plan_faithfulness": r["plan_faithfulness"],
                     "targeting_leverage": r["targeting_leverage"],
                     "v_violation_total": r["v_violation_total"],
                     "objective": r["objective"], "violation_hours": r["violation_hours"]})
    return summarise(rows)

# ===== upstream cell 27 =====
# ---------- E6: deviation attribution ----------

def exp6_attribution(spec, llm, seeds=SEEDS[:3], **kw) -> pd.DataFrame:
    """Who deviates from the plan: by archetype and by electrical position."""
    frames = []
    for mode, seed in itertools.product(PLAN_MODES, seeds):
        cfg = EpisodeConfig(seed=seed, declaration="forced", forced_mode=mode,
                            label=f"E6-{mode}", **kw)
        out = run_episode(cfg, spec, llm)
        r = out["realized"]
        if r.empty:
            continue
        r = r.assign(mode=mode, seed=seed)
        frames.append(r)
    return pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()
